<template>
  <main class="hh-page counter-list">
    <section class="counter-hero"><div><span>CONTINUIDAD ASISTENCIAL</span><h1>Contrarreferencias</h1><p>Consulte los egresos remitidos y sus planes de seguimiento.</p></div><router-link to="/contrareferencias/seguimiento" class="btn btn-light text-primary"><i class="ph ph-calendar-warning me-1"></i>Seguimiento urgente</router-link></section>
    <b-card no-body class="filters mt-4"><b-card-body><form class="row g-3" @submit.prevent="load"><div class="col-md-3"><label class="form-label">Condición de egreso</label><select v-model="filters.condicion_egreso" class="form-select"><option value="">Todas</option><option v-for="item in conditions" :key="id(item)" :value="id(item)">{{name(item)}}</option></select></div><div class="col-md-3"><label class="form-label">Médico</label><select v-model="filters.medico_id" class="form-select"><option value="">Todos</option><option v-for="item in doctors" :key="id(item)" :value="id(item)">{{name(item)}}</option></select></div><div class="col-md-2"><label class="form-label">Seguimiento</label><select v-model="filters.requiere_seguimiento" class="form-select"><option value="">Todos</option><option value="1">Requiere</option><option value="0">No requiere</option></select></div><div class="col-md-2"><label class="form-label">Desde</label><input v-model="filters.fecha_inicio" type="date" class="form-control"></div><div class="col-md-2"><label class="form-label">Hasta</label><input v-model="filters.fecha_fin" type="date" class="form-control"></div><div class="col-12 d-flex justify-content-end gap-2"><button type="button" class="btn btn-outline-secondary" @click="clear">Limpiar</button><button class="btn btn-primary" :disabled="loading"><span v-if="loading" class="spinner-border spinner-border-sm me-2"></span>Buscar</button></div></form></b-card-body></b-card>
    <div v-if="error" class="alert alert-danger mt-3">{{error}}</div><section class="results mt-4"><header><div><small>REGISTROS</small><h2>Contrarreferencias encontradas</h2></div><label><i class="ph ph-magnifying-glass"></i><input v-model="search" placeholder="Buscar paciente o referencia"><span>{{filtered.length}}</span></label></header><div v-if="!loading&&!filtered.length" class="empty"><i class="ph ph-arrow-bend-up-left"></i><h3>Sin contrarreferencias</h3><p>No existen registros para los filtros seleccionados.</p></div><div v-else class="cards"><article v-for="item in filtered" :key="item.id"><header><span><i class="ph ph-arrow-bend-up-left"></i></span><div><small>{{item.referencia?.numero_referencia||`Referencia #${item.referencia_id}`}}</small><h3>{{patientName(item)}}</h3><p>{{item.referencia?.paciente?.identificacion}}</p></div><em>{{item.condicion_egreso?.nombre||item.condicion_egreso}}</em></header><div class="card-body"><div><small>Diagnóstico final</small><strong>{{item.diagnostico_final?.nombre||item.diagnostico_final_texto||'No informado'}}</strong></div><div><small>Médico</small><strong>{{item.medico_contrarefiere?.name||item.medico?.name||'No informado'}}</strong></div><div><small>Próximo control</small><strong>{{item.requiere_seguimiento?formatDate(item.fecha_proximo_control):'No requiere'}}</strong></div></div><footer><router-link :to="`/referencias/${item.referencia_id||item.referencia?.id}/contrareferencia`" class="btn btn-sm btn-outline-primary">Ver/editar</router-link><router-link :to="`/contrareferencias/${item.id}/documentos`" class="btn btn-sm btn-outline-secondary"><i class="ph ph-files me-1"></i>Documentos</router-link></footer></article></div></section>
  </main>
</template>
<script setup>
import{computed,onMounted,reactive,ref}from'vue';import{obtenerMensajeError}from'@/services/api';import{consultarCatalogosReferencia,listarContrareferencias,listarMedicosReceptores}from'@/services/referencias';const items=ref([]),conditions=ref([]),doctors=ref([]),loading=ref(false),error=ref(''),search=ref(''),filters=reactive({condicion_egreso:'',medico_id:'',requiere_seguimiento:'',fecha_inicio:'',fecha_fin:''});const array=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:[],id=x=>x.id??x.id_usuario,name=x=>x.nombre??x.name??x.descripcion,patientName=x=>x.referencia?.paciente?.nombre||x.paciente?.nombre||'Paciente no informado',formatDate=v=>v?new Intl.DateTimeFormat('es-CO',{dateStyle:'medium'}).format(new Date(`${String(v).slice(0,10)}T00:00:00`)):'Sin fecha',filtered=computed(()=>{const t=search.value.toLowerCase();return items.value.filter(x=>[patientName(x),x.referencia?.numero_referencia,x.referencia?.paciente?.identificacion].join(' ').toLowerCase().includes(t))});async function load(){loading.value=true;error.value='';try{items.value=array(await listarContrareferencias({...filters}))}catch(e){error.value=obtenerMensajeError(e)}finally{loading.value=false}}function clear(){Object.keys(filters).forEach(k=>filters[k]='');search.value='';load()}onMounted(async()=>{const[c,d]=await Promise.allSettled([consultarCatalogosReferencia(),listarMedicosReceptores()]);if(c.status==='fulfilled'){const s=c.value?.data||c.value;conditions.value=s.condiciones_egreso||[]}if(d.status==='fulfilled')doctors.value=array(d.value);await load()})
</script>
<style scoped>.counter-hero{display:flex;align-items:center;justify-content:space-between;padding:1.4rem 1.5rem;border-radius:1rem;background:linear-gradient(120deg,#0b5587,#148fbc);color:#fff}.counter-hero span,.results>header small{font-size:.6rem;font-weight:800;letter-spacing:.08em}.counter-hero h1{margin:.2rem 0;font-size:1.55rem}.counter-hero p{margin:0;opacity:.82}.filters,.results{overflow:hidden;border:1px solid #dfe7ee;border-radius:1rem;background:#fff;box-shadow:0 9px 28px rgba(25,63,95,.06)}.results>header{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.2rem;border-bottom:1px solid #e3e9ef;background:#fbfcfe}.results h2{margin:.1rem 0;font-size:1.05rem}.results>header label{display:flex;align-items:center;gap:.4rem;padding:.4rem .6rem;border:1px solid #dfe6ec;border-radius:.55rem;background:#fff}.results>header input{border:0;outline:0;font-size:.7rem}.results>header span{color:var(--bs-primary);font-size:.65rem}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:.8rem;padding:1rem}.cards>article{overflow:hidden;border:1px solid #e0e7ed;border-radius:.8rem}.cards article>header{display:flex;align-items:center;gap:.65rem;padding:.85rem;border-bottom:1px solid #e7ecf0}.cards header>span{display:grid;place-items:center;width:40px;height:40px;border-radius:11px;background:#e8f4fc;color:var(--bs-primary);font-size:1.1rem}.cards header>div{min-width:0;flex:1}.cards header small{color:#718096;font-size:.58rem}.cards h3{margin:.1rem 0;font-size:.84rem}.cards header p{margin:0;color:#8290a0;font-size:.62rem}.cards header em{padding:.28rem .5rem;border-radius:20px;background:#e8f8f0;color:#28845f;font-size:.6rem;font-style:normal}.card-body{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem;padding:.8rem}.card-body small,.card-body strong{display:block}.card-body small{color:#8592a1;font-size:.56rem}.card-body strong{overflow:hidden;font-size:.65rem;text-overflow:ellipsis;white-space:nowrap}.cards article>footer{display:flex;justify-content:flex-end;gap:.4rem;padding:.7rem .85rem;border-top:1px solid #e7ecf0}.empty{text-align:center;padding:4rem;color:#718096}.empty>i{font-size:2.8rem;color:#adc2d1}.empty h3{margin:.6rem 0 .2rem;font-size:1rem}@media(max-width:800px){.cards{grid-template-columns:1fr}.counter-hero{align-items:flex-start;flex-direction:column;gap:1rem}}</style>
